const url = process.env.URL;
if (!url) throw new Error('Missing URL');
const mod = await import('web-fetch');
const fetchFn = mod.default || mod;
globalThis.rawBody = await fetchFn(url);

const raw = globalThis.rawBody;
let parsed;
try {
  parsed = JSON.parse(raw);
} catch {
  parsed = raw;
}
if (typeof parsed === 'object') {
  globalThis.parsed = JSON.stringify(parsed);
} else {
  globalThis.parsed = String(parsed);
}
